describe('Image Upload from Clipboard', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should successfully upload an image from the clipboard', () => {
        cy.get('input[type="file"]').then(($input) => {
            const clipboardImage = new ClipboardEvent('paste', {
                clipboardData: new DataTransfer()
            });
            const file = new File([''], 'image.png', { type: 'image/png' });
            clipboardImage.clipboardData.setData('Files', [file]);
            document.dispatchEvent(clipboardImage);
        });

        cy.get('.upload-area').trigger('paste');
        cy.get('.upload-area').should('contain', 'image.png'); // Adjust based on how the UI reflects the upload
    });

    it('should show an error message when pasting a non-image file', () => {
        cy.get('input[type="file"]').then(($input) => {
            const clipboardText = new ClipboardEvent('paste', {
                clipboardData: new DataTransfer()
            });
            clipboardText.clipboardData.setData('text/plain', 'This is not an image');
            document.dispatchEvent(clipboardText);
        });

        cy.get('.upload-area').trigger('paste');
        cy.get('.error-message').should('be.visible').and('contain', 'Please paste a valid image'); // Adjust based on actual error message
    });
});
